 if(!/\^PW831\b/.test(zpl)||!(/\^FT147,30\^BCR/.test(zpl)))throw Error('Etiket şablonu ürün alanı için tanınmadı; barkoda yazı eklenmedi.');
 const amountText=gaziFooterAmount(order),productWidth=amountText?540:640;
 const words=gaziProductText(order).split(' ');let lines,size,font;
 for(const s of [24,20,16,14]){
  const f=GAZI_FOOTER_FONTS[s],width=t=>Array.from(t).reduce((a,c)=>a+(f[c]||f['?'])[0],0);
  let out=[],line='',valid=true;
  for(const word of words){if(width(word)>productWidth){valid=false;break;}const test=line?line+' '+word:word;if(width(test)>productWidth){out.push(line);line=word;}else line=test;}
  if(line)out.push(line);if(valid&&out.length<=3){lines=out;size=s;font=f;break;}
 }
 if(!lines){
  // Uzun siparişlerde yazdırmayı engelleme; etiket üzerinde kısa tanım kullan.
  const shortText=`Sipariş: ${order.siparis_no} / Karışık ürünler`;
  const f=GAZI_FOOTER_FONTS[20],measure=t=>Array.from(t).reduce((a,c)=>a+(f[c]||f['?'])[0],0);
  if(measure(shortText)>productWidth)throw Error('Kısa ürün açıklaması etiket alanına sığmadı.');
  lines=[shortText];size=20;font=f;
 }
 const width=90,height=640,rowBytes=Math.ceil(width/8),bytes=new Uint8Array(rowBytes*height);
 lines.forEach((line,i)=>{let pen=0;for(const ch of line){const [advance,bitmap]=font[ch]||font['?'];bitmap.forEach((row,y)=>{for(let x=0;x<advance;x++){if(!(parseInt(row,16)&(2**(advance-1-x))))continue;const px=89-(i*30+y),py=pen+x;if(px>=0&&px<90&&py<640)bytes[py*rowBytes+(px>>3)]|=128>>(px&7);}});pen+=advance;}});
