  // Draw in an upright 90x90 box, then rotate into the reserved footer area.
  const pixel=(x,y)=>{if(x>=0&&x<90&&y>=0&&y<90)bytes[(550+x)*rowBytes+((89-y)>>3)]|=128>>((89-y)&7);};
  for(let y=0;y<90;y++)for(let x=0;x<90;x++)if(x<2||x>=88||y<2||y>=88)pixel(x,y);
